# Generated by build.py from recipe.yml for recipe smtp-keep-mail-across-restarts. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'data', '--mail-domain', 'example.com', '--mailbox', 'shop@example.com:shoppass', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/example.com --next -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8082/example.com
curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -o NUL -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1" --next -sS --retry 10 --retry-all-errors --retry-delay 1 -o NUL -u ann@example.com:annpass "imap://127.0.0.1:8083/INBOX;UID=1"
curl.exe -sS -u ann@example.com:annpass -X "STORE 1 +FLAGS \Flagged" imap://127.0.0.1:8081/INBOX
try { curl.exe -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT" } finally { Stop-Process $server0 }
